// src/constants/foodItems.ts
// Curated nutrition library for the manual add-food flow across the 5
// meal-time sections (Morning Drink, Breakfast, Lunch, Evening Snacks,
// Dinner). Breakfast/Lunch/Evening Snacks/Dinner are sourced from the
// existing FBR nutrition-plan database (src/constants/nutritionPlans);
// Morning Drink has no equivalent there, so it is hand-curated. Calorie
// and macro defaults are expert-judgment estimates per dish — editable
// before adding. See app/(client)/workout-plan.tsx AddExerciseModal pattern.

export interface FoodItemDefault {
  id: string;
  name: string;
  defaultQuantity: string;
  defaultCalories: number;
  defaultProteinG: number;
  defaultCarbsG: number;
  defaultFatG: number;
}

